  await consumeInternalDeploymentApproval({
    ownerApprovalId: approvalId,
    requestedCommitSha,
    deploymentAction: action,
  });
  await logCheckpoint(task.id, runId, 'INTERNAL_APPROVAL_CONSUMED', { action, approvalId });
}

